105	// `run --model cycle`: one cycle-accurate engine alone, from reset (no QEMU,
106	// no --resume-from-qemu), transparent passthrough -- cycles surface in the
107	// engine's own output. Unlike fast, this must discover the Verilator build(s)
108	// to resolve the engine (explicit --engine, else the sole one).
109	int run_accurate(const Cli& cli) {
110	  // Reject a missing/extra ELF before discovery so a CLI typo does not spawn a
111	  // --describe subprocess per Verilator build only to fail on the argument.
112	  if (int rc = check_one_elf(cli, "cycle")) return rc;
113	  // --mem-size is validated but has nothing to size: the cycle engine always
114	  // models its full DRAM window. Say so instead of silently ignoring it.
115	  if (!cli.mem_size.empty()) {
116	    std::string se;
117	    if (parse_size(cli.mem_size, se); !se.empty()) {
118	      std::fprintf(stderr, "andes-sim run --model cycle: --mem-size: %s\n",
119	                   se.c_str());
120	      return 2;
121	    }
122	    std::fprintf(stderr,
123	                 "[andes-sim] --mem-size: the cycle engine models its full "
124	                 "DRAM window; nothing to size\n");
125	  }
126	  Discovery disc = discover_engines();
127	  std::string err;
128	  const EngineDescriptor* eng =
129	      resolve_accurate_engine(disc.engines, cli.engine, err);
130	  if (!eng) {
131	    std::fprintf(stderr, "andes-sim run --model cycle: %s\n", err.c_str());
132	    // Surface why an expected engine may be absent (failed --describe, etc.).
133	    for (const std::string& w : disc.warnings)
134	      std::fprintf(stderr, "andes-sim: skipped engine: %s\n", w.c_str());
135	    return 2;
136	  }
137	  // --cosim on the cycle model = lock-step DV co-sim against a QEMU oracle,
138	  // not a plain standalone run.
139	  if (cli.cosim) return run_cosim_lockstep(cli, *eng);
140	  return run_standalone(cli, *eng, "cycle");
141	}
